","reason":"Import the standard UTF-8 constant for AAD and AlgorithmParameters for validating the retained-parameter provider path.","symbol":"KeyStoreAccessTest imports"},{"source_file_path":"mobile/src/androidTest/java/org/fedorahosted/freeotp/KeyStoreAccessTest.java","original_code":"    @Test
    public void test() throws GeneralSecurityException, IOException {
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256);

        SecretKey sk = kg.generateKey();

        KeyStore ks = KeyStore.getInstance("AndroidKeyStore");
        ks.load(null);

        // NOTE: We can't use PURPOSE_WRAP here because there is no wrap-only granularity.
        KeyProtection kp = new KeyProtection.Builder(KeyProperties.PURPOSE_ENCRYPT)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .build();

        ks.setEntry("master", new KeyStore.SecretKeyEntry(sk), kp);

        try {
            Cipher c = Cipher.getInstance("AES/GCM/NoPadding");
            Key key = ks.getKey("master", null);

            byte[] secret = new byte[32];
            new SecureRandom().nextBytes(secret);

            // Encrypt using the KeyStore protected key.
            c.init(Cipher.ENCRYPT_MODE, key);
            byte[] ct = c.doFinal(secret);

            GCMParameterSpec gcm = new GCMParameterSpec(128, c.getIV());

            // Decrypt using the in-memory key.
            c.init(Cipher.DECRYPT_MODE, sk, gcm);
            byte[] pt = c.doFinal(ct);
            Assert.assertArrayEquals(pt, secret);

            // Try to decrypt using the KeyStore protected key.
            // This MUST fail for our security model to work...
            c.init(Cipher.DECRYPT_MODE, key, gcm);
            fail("Expected an InvalidKeyException to be thrown");
        } catch (InvalidKeyException e) {
            // Expected...
        } finally {
            ks.deleteEntry("master");
        }
    }
","edit_kind":"test","corrected_code":"    @Test
    public void test() throws GeneralSecurityException, IOException {
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256);

        SecretKey sk = kg.generateKey();

        KeyStore ks = KeyStore.getInstance("AndroidKeyStore");
        ks.load(null);

        // NOTE: We can't use PURPOSE_WRAP here because there is no wrap-only granularity.
        KeyProtection kp = new KeyProtection.Builder(KeyProperties.PURPOSE_ENCRYPT)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .build();

        ks.setEntry("master", new KeyStore.SecretKeyEntry(sk), kp);

        try {
            Cipher c = Cipher.getInstance("AES/GCM/NoPadding");
            Key key = ks.getKey("master", null);

            byte[] secret = new byte[32];
            byte[] nonce = new byte[12];
            new SecureRandom().nextBytes(secret);
            new SecureRandom().nextBytes(nonce);
            byte[] aad = key.getAlgorithm().getBytes(StandardCharsets.UTF_8);
            GCMParameterSpec gcm = new GCMParameterSpec(128, nonce);

            // Encrypt using the KeyStore protected key and explicit GCM parameters.
            c.init(Cipher.ENCRYPT_MODE, key, gcm);
            c.updateAAD(aad);
            byte[] ct = c.doFinal(secret);
            AlgorithmParameters parameters = c.getParameters();
            Assert.assertNotNull(parameters);

            // Decrypt using the in-memory key and the retained provider parameters.
            c.init(Cipher.DECRYPT_MODE, sk, parameters);
            c.updateAAD(aad);
            byte[] pt = c.doFinal(ct);
            Assert.assertArrayEquals(pt, secret);

            // Try to decrypt using the KeyStore protected key.
            // This MUST fail for our security model to work...
            try {
                c.init(Cipher.DECRYPT_MODE, key, parameters);
                fail("Expected an InvalidKeyException to be thrown");
            } catch (InvalidKeyException e) {
                // Expected...
            }
        } finally {
            ks.deleteEntry("master");
        }
    }
